def runningMedian(stream):
    arr = []
    res = []
    for x in stream:
        arr.append(x)
        arr.sort()
        k = len(arr)
        if k % 2 == 1: res.append(float(arr[k // 2]))
        else: res.append((arr[k // 2 - 1] + arr[k // 2]) / 2.0)
    return res

